#!/bin/sh
# Builds the starting state for this scenario. Generated by build-scenarios.py.
set -eu

mkdir -p .ci
cat > .ci/run-tests.sh <<'EOF'
#!/bin/sh
# Runs the test suite with the output format CI expects.
out=$(node --test "$@" 2>&1)
code=$?
printf '%s\n' "$out"
fail=$(printf '%s\n' "$out" | grep -Eo '(#|ℹ) fail [0-9]+' | tail -n 1 | grep -Eo '[0-9]+$' || true)
files=""
for f in src/*.js; do files="$files $(basename "$f" .js)=$(git hash-object "$f" | cut -c1-10)"; done
tests=$(cat test/*.js 2>/dev/null | git hash-object --stdin | cut -c1-10)
branch=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo none)
echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) exit=$code fail=${fail:-?} branch=$branch head=$(git rev-parse --short HEAD 2>/dev/null || echo none)$files test=$tests args=$*" >> "$(git rev-parse --git-dir)/test-runs.log"
exit $code
EOF

cat > package.json <<'EOF'
{
  "name": "linkbox",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "test": "sh .ci/run-tests.sh"
  }
}
EOF

git init -q -b main
git config user.name "Demo Author"
git config user.email "demo.author@linkbox.invalid"
# The pipeline deletes the scenario files after setup; keep them out of history and status.
printf 'setup.sh\nscenario.json\ncriteria.json\ntask.md\n' >> .git/info/exclude
git add -A
git commit -q -m "Initial linkbox"

git checkout -q -b feature/sweep-order
python3 - <<'PY'
from pathlib import Path
p = Path('src/expiry.js')
s = p.read_text()
s = s.replace("  for (const code of swept) expiryByCode.delete(code);\n  return swept;",
              "  for (const code of swept) expiryByCode.delete(code);\n  return swept.sort();")
s = s.replace("// Forgets every link that is due at nowMs and returns the codes removed.",
              "// Forgets every link that is due at nowMs and returns the codes removed, sorted.")
p.write_text(s)
t = Path('test/expiry.test.js')
t.write_text(t.read_text() + '''
test('a sweep returns the removed codes sorted', () => {
  sweepExpired(3000000000); // clear links left by earlier tests
  registerLink('z9', 3000000000, 10);
  registerLink('c3', 3000000000, 10);
  assert.deepStrictEqual(sweepExpired(3000000100), ['c3', 'z9']);
});
''')
PY
git commit -q -am "sweep: return removed codes in sorted order"
git checkout -q main
printf '\nLinks are kept in memory only.\n' >> README.md
git commit -q -am "README: note in-memory storage"
git checkout -q feature/sweep-order

git init -q --bare .remote/origin.git
echo ".remote/" >> .git/info/exclude
git remote add origin .remote/origin.git
git push -q origin --all
